import { LABEL_ALIGNMENT } from '../constants.js';
import { LabelAlignment } from '../types/range-legend.internal.js';

const DEFAULT_POSITION_X_VERTICAL = 12;

export const getVerticalLabelPosition = (
  labelHeight: number,
  itemStartPosition: number,
  segmentSize: number,
  alignment: LabelAlignment,
) => {
  const labelPositionX = DEFAULT_POSITION_X_VERTICAL;

  switch (alignment) {
    case LABEL_ALIGNMENT.START:
      return {
        labelPositionX,
        labelPositionY: Math.floor(itemStartPosition + labelHeight / 2),
      };
    case LABEL_ALIGNMENT.END: {
      return {
        labelPositionX,
        labelPositionY: Math.floor(
          itemStartPosition + segmentSize + labelHeight / 2,
        ),
      };
    }
    case LABEL_ALIGNMENT.CENTER: {
      return {
        labelPositionX,
        labelPositionY: Math.floor(
          itemStartPosition + segmentSize / 2 + labelHeight / 2,
        ),
      };
    }
  }
};
